// Custom Worker entry: wraps the OpenNext (Next.js) handler and adds the admin
// dashboard backend (a Durable Object) plus the 5-minute cron that sends
// outreach emails and checks for replies.
// @ts-ignore `.open-next/worker.js` is generated by `npm run build`
import { default as nextHandler } from "./.open-next/worker.js";
import type { Env } from "./worker/store";

export { AdminStore } from "./worker/store";

const store = (env: Env) => env.ADMIN_STORE.get(env.ADMIN_STORE.idFromName("main"));
const PRIMARY_HOST = "ramjanaliakash.com";
const REDIRECT_HOSTS = new Set(["www.ramjanaliakash.com", "ramjan-ali-tracker.ramjan-ali.workers.dev"]);

function withAssetCache(response: Response, pathname: string, method: string) {
  if (method !== "GET" && method !== "HEAD") return response;
  const cacheable =
    pathname.startsWith("/_next/static/") || pathname === "/_next/image" || pathname.startsWith("/assets/");
  if (!cacheable || !response.ok) return response;
  const headers = new Headers(response.headers);
  headers.set("Cache-Control", "public, max-age=31536000, immutable");
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

function withPrivateRobots(response: Response) {
  const headers = new Headers(response.headers);
  headers.set("X-Robots-Tag", "noindex, nofollow, noarchive");
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);
    if (url.protocol !== "https:" || REDIRECT_HOSTS.has(url.hostname)) {
      url.protocol = "https:";
      if (REDIRECT_HOSTS.has(url.hostname)) url.hostname = PRIMARY_HOST;
      url.port = "";
      return Response.redirect(url.toString(), 308);
    }
    const { pathname } = url;
    if (pathname.startsWith("/api/admin/") || pathname === "/api/lead" || pathname === "/api/hooks/cal") {
      return withPrivateRobots(await store(env).fetch(request));
    }
    const response = await nextHandler.fetch(request, env, ctx);
    return withAssetCache(response, pathname, request.method);
  },
  async scheduled(_controller: ScheduledController, env: Env, ctx: ExecutionContext): Promise<void> {
    ctx.waitUntil(store(env).tick());
  },
} satisfies ExportedHandler<Env>;
